const findings = await read.findingsUnder(under);
if ("refused" in findings) {
	failures.push(`round ${round.id} ${findings.refused}`);
	continue;
}
verdicts.push({ verdict: findings, own: round.revision === gate });
const contents = read.contents(own);
if (!("refused" in contents)) {
	ended.push(...contents.ended);
	unjudged.push(...contents.unjudged);
}
const covers =
	round.revision !== gate
		? { refused: `reviewed ${round.revision}, not this merge's ${gate}` }
		: await coverage(set, round, read, { ...under, revision }, context.tier);

passes(): boolean {
	const { verdict } = this;
	return (
		verdict.status !== "not-reviewed" && verdict.findings.block.length + verdict.findings.acknowledge.length === 0
	);
}

// The host caps a finding its failed verifier never judged at advisory, and reads the round as not reviewed.
if (claim.checks.includes("verifier") && !(reviewed.ran ?? []).some(({ name }) => name === "verifier"))
	return { refused: "did not run its verifier, so not every finding it raised was judged", would: covers };
return { covers, below: (reviewed.ran ?? []).filter((check) => !atFloor(check)) };

const unjudged = options.unverified === true && this.unjudged();
return this.#claims()
	.map((claim): FindingDecision => {
		// The fence again, where the keys are read: a lowering never takes a finding into silence, whatever they
		// said when the verifier asked. The lens's severity then stands. An unlowered finding's original severity
		// is its own, so this changes only a lowered one.
		const asLowered = walk.decide(claim);
		const severity = asLowered.resolution === "silent" ? this.original() : claim.severity;
		const decided = severity === claim.severity ? asLowered : walk.decide({ ...claim, severity });
		const preExisting = cause === "pre-existing" ? walk.preExistingCap(severity) : undefined;
		const decidedBy = withoutUndefined({
			file: decided.file,
			lens: decided.lens,
			check: claim.check,
			rule: claim.rule ?? claim.group,
			requirement: { entry: decided.requirement.entry, key: decided.requirement.key },
			ceiling: decided.ceiling && { entry: decided.ceiling.entry, key: decided.ceiling.key },
		}) as DecidedBy;
		const limits: [Pick<DecidedBy, "cap" | "capBy">, Resolution | undefined][] = [
			[withoutUndefined({ cap: "pre-existing", capBy: preExisting?.by }) as DecidedBy, preExisting?.value],
			[{ cap: "unproven-cause" }, unproven ? "advisory" : undefined],
			[{ cap: "unverified" }, unjudged ? "advisory" : undefined],
		];

} else if (record.kind === "verification") {
	const { check, claims: judged, outcomes } = record.payload as VerificationPayload;
	if (check === null) return { refused: "names a verification without the verifier's check" };
	verifier = present(check) as unknown as CheckRecord;
	claims.push(...(judged as unknown as VerificationClaim[]));
	for (const { candidate } of outcomes) asked.add(candidate);
}

- **Findings** are the union of every counted round's findings, each at its strictest resolution, then its lower severity. A block or an unresolved acknowledgement in any round fails the gate, so a later clean round never hides a finding.
- **The round of the merge keeps every finding.** The gate drops a finding whose file is not in the merge's diff only from a round whose revision is not the merge's own, the stacked case the maintainer's reading of 2026-11-18 covered. A round of exactly M..H hands over every finding, a pre-existing one in a file the change did not touch included, so an acknowledgement its policy keeps still fails the gate, as rule 9 says.
- **Coverage**: a check of the base tip's tier counts as covered when some sound round of exactly M..H ran it. A check no such round ran leaves the gate not reviewed, naming it. A round is sound when all of these hold:
  - every record it names is found, of its own revision, and it replaces no round;
  - its account names the base tip's tier and allows exactly the skips that tier gives;
  - its records stand as reviewed under the base tip's resolution policy;
  - its verifier ran, when its account names one. The host caps a finding a failed verifier never judged at advisory and reads that round as not reviewed, so the round covers nothing, though its findings still count.

// The one listing the review fills each dismissal's `supersedes` from, in verification and export alike; a store
// that cannot be listed fails the review, as a failed export does.
const held = request.records === undefined ? [] : await request.records.list(changeset.id);

